const today = new Date();
const start = new Date(today);
start.setDate(start.getDate() - 180);
return [{
  json: {
    start_date: start.toISOString().slice(0,10),
    end_date: today.toISOString().slice(0,10),
    generated_at: today.toISOString().slice(0,16).replace('T',' '),
    context: `Today is ${today.toISOString().slice(0,10)}. Fetch Oura data from ${start.toISOString().slice(0,10)} to ${today.toISOString().slice(0,10)}.`
  }
}];

